def git_env(temp_dir):
    home = os.path.join(temp_dir, 'home')
    os.mkdir(home)
    env = {key: value for key, value in os.environ.items() if not key.startswith(('GIT_', 'LD_', 'PYTHON'))}
    env.update({'GIT_CONFIG_NOSYSTEM': '1', 'GIT_CONFIG_GLOBAL': os.devnull, 'GIT_CONFIG_SYSTEM': os.devnull, 'HOME': home, 'XDG_CONFIG_HOME': os.path.join(home, '.config'), 'PATH': '/usr/bin:/bin', 'GIT_OPTIONAL_LOCKS': '0', 'GIT_PAGER': 'cat', 'LC_ALL': 'C', 'GIT_CEILING_DIRECTORIES': os.path.dirname(os.path.abspath(temp_dir))})
    return env
